        stack=[(r,c)]; seen.add((r,c)); comp=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and g[yy][xx]==2 and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        if len(comp)>1:
          r0=min(y for y,x in comp); r1=max(y for y,x in comp)
          c0=min(x for y,x in comp); c1=max(x for y,x in comp)
          # highlighted cells on the object's four extremal diagonals
          for y,x in comp:
            if (y==r0 and x==c0) or (y==r1 and x==c1): g[y][x]=8
